'use strict';
const FACET_TYPES={medical:{label:'医疗资源',icon:'＋',short:'医疗',color:'#528d87',hint:'从医院资源，看见就医路径与服务半径'},transport:{label:'交通连接',icon:'╬',short:'交通',color:'#5c7fa6',hint:'从城市枢纽，看见通勤与跨城联系'},culture:{label:'文化实力',icon:'◈',short:'文化',color:'#b47c57',hint:'从博物馆、舞台与传统，看见文化生活'},education:{label:'教育科研',icon:'▤',short:'科教',color:'#8570a5',hint:'从高校与科研资源，看见知识网络'},nature:{label:'公园与休闲',icon:'◎',short:'休闲',color:'#6b8e61',hint:'从公园、山水与步行空间，看见日常活动'}};
function facetFor(c,topic=state.facet){return window.CITY_FACETS?.[c.name]?.[topic];}
window.syncFacetSearch=function(){const q=state.search.trim().toLowerCase();if(!q)return;const matches=Object.entries(window.CITY_FACETS?.[selected().name]||{}).flatMap(([key,f])=>f.resources.flatMap((r,i)=>r.name.toLowerCase().includes(q)?[{key,i}]:[]));const topics=[...new Set(matches.map(m=>m.key))];const current=matches.find(m=>m.key===state.facet);if(current)state.resource=current.i;else if(topics.length===1){state.facet=topics[0];state.resource=matches[0].i;}};
function facetResource(f){const r=f.resources[state.resource]||f.resources[0];return `<div class="resource-detail"><div class="kicker">代表资源 / ${esc(r.type)}</div><h3>${esc(r.name)}</h3><p>${esc(r.detail)}</p><div class="resource-area"><span class="caption">所在片区 / 服务范围</span><b>${esc(r.area)}</b></div></div>`;}
function facetReferences(f){return (f.references||[]).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)}<span>官网参考</span></a>`).join('');}
function facetCompare(){const cs=state.compare.map(id=>CITIES.find(c=>c.id===id));return `<section class="panel facet-comparison"><div class="comparison-top"><div><div class="kicker">同一个切面 / 放在一起看</div><h2>${FACET_TYPES[state.facet].label}，城市各有侧重</h2></div><small class="caption">最多 4 城</small></div><div class="comparison-chips">${cs.map(c=>`<button class="remove-chip" data-compare="${c.id}" aria-label="从切面对比移除${c.name}">${c.name} ×</button>`).join('')}</div>${cs.length?`<div class="scroll-table"><table class="compare-table facet-compare-table"><caption class="sr-only">所选城市${FACET_TYPES[state.facet].label}对比</caption><thead><tr><th>观察点</th>${cs.map(c=>`<th>${c.name}</th>`).join('')}</tr></thead><tbody><tr><th>城市特点</th>${cs.map(c=>`<td>${esc(facetFor(c).signature)}</td>`).join('')}</tr><tr><th>代表资源</th>${cs.map(c=>`<td>${facetFor(c).resources.map(r=>esc(r.name)).join('<br>')}</td>`).join('')}</tr><tr><th>日常取舍</th>${cs.map(c=>`<td>${esc(facetFor(c).access[0])}</td>`).join('')}</tr><tr><th>实地核对</th>${cs.map(c=>`<td>${esc(facetFor(c).check[0])}</td>`).join('')}</tr></tbody></table></div>`:'<p class="caption" style="margin-top:20px">选择下方城市的 ＋，加入切面对比。</p>'}<p class="caption" style="margin:16px 0 0">代表案例是编辑选读，未穷尽当地资源，也没有按机构数量或声誉打分。</p></section>`;}
function facetMatrix(){return `<section class="panel facet-matrix"><div class="panel-head"><div><h2>十城 × 五个切面</h2><p class="caption" style="margin:9px 0 0">点选任意格子，切换城市和观察视角。</p></div><small class="caption">特点对照 · 无强弱排名</small></div><div class="scroll-table"><table class="facet-matrix-table"><caption class="sr-only">十城医疗、交通、文化、教育与休闲特点对照</caption><thead><tr><th>城市</th>${Object.entries(FACET_TYPES).map(([key,t])=>`<th class="${state.facet===key?'column-focus':''}">${t.short}</th>`).join('')}<th>对比</th></tr></thead><tbody>${filtered().map(c=>`<tr><th scope="row"><button data-city="${c.id}">${c.name}</button></th>${Object.entries(FACET_TYPES).map(([key,t])=>`<td class="${state.facet===key?'column-focus':''}"><button class="matrix-cell ${state.city===c.id&&state.facet===key?'selected':''}" data-facet-cell="${c.id}:${key}" aria-label="探索${c.name}的${t.label}">${esc(facetFor(c,key).signature)}</button></td>`).join('')}<td><button class="compare-check ${state.compare.includes(c.id)?'checked':''}" data-compare="${c.id}" aria-label="${state.compare.includes(c.id)?'移除':'加入'}${c.name}切面对比" aria-pressed="${state.compare.includes(c.id)}">${state.compare.includes(c.id)?'✓':'＋'}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
window.facetsView=function(){const cs=filtered();if(!cs.length)return '<div class="panel empty">没有匹配的城市或资源。试试医院、高校、场馆名称，或切换城市群。</div>';const c=selected(),f=facetFor(c),t=FACET_TYPES[state.facet];if(!f)return '<div class="panel empty">该城市切面资料暂未就绪。</div>';return `<div class="facet-top" style="--facet-color:${t.color}"><div class="facet-top-title"><div><div class="kicker">城市切面 / 从资源走向日常</div><h2>${c.name}<span> / ${t.label}</span></h2></div><span class="facet-location">${c.region} · ${c.en}</span></div>${cityStrip()}<div class="facet-switch" role="group" aria-label="选择城市切面">${Object.entries(FACET_TYPES).map(([key,v])=>`<button data-facet="${key}" class="${state.facet===key?'selected':''}" aria-pressed="${state.facet===key}"><span aria-hidden="true">${v.icon}</span>${v.label}</button>`).join('')}</div></div><div class="facet-layout" style="--facet-color:${t.color}"><article class="panel facet-main"><div class="kicker">${t.hint}</div><h2 class="intro-title">${esc(f.headline)}</h2><p class="intro-text">${esc(f.summary)}</p><div class="facet-section-label"><h3>先认识三个代表资源</h3><span class="caption">点选查看 · 样本，不是完整清单</span></div><div class="resource-selector" role="group" aria-label="选择代表资源">${f.resources.map((r,i)=>`<button data-resource="${i}" class="resource-card ${state.resource===i?'selected':''}" aria-pressed="${state.resource===i}"><span class="resource-number">${String(i+1).padStart(2,'0')}</span><span class="resource-type">${esc(r.type)}</span><b>${esc(r.name)}</b><small>${esc(r.area)}</small></button>`).join('')}</div><div id="facet-resource" aria-live="polite">${facetResource(f)}</div><div class="facet-section-label" style="margin-top:28px"><h3>实力如何变成日常体验</h3></div><ol class="access-list">${f.access.map((a,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(a)}</p></li>`).join('')}</ol></article><aside class="facet-side"><section class="panel facet-check"><div class="kicker">带着问题去实地验证</div><h2>对你而言，能否用得上</h2><ol>${f.check.map(a=>`<li>${esc(a)}</li>`).join('')}</ol><button class="secondary" data-compare="${c.id}" aria-pressed="${state.compare.includes(c.id)}">${state.compare.includes(c.id)?'从切面对比移除'+c.name:'加入'+c.name+'切面对比'}</button></section><section class="panel facet-links"><h3>进一步核对</h3>${facetReferences(f)}<p class="caption">机构与资源为稳定事实的编辑选读，未逐项实时核验。链接包含机构、运营主体与政府参考入口；涉及院区、开放和预约规则，请在对应官方渠道进一步查找。</p></section><div class="facet-boundary"><b>资源丰富 ≠ 个人可及</b><p>${{medical:'医院的城市声誉不能代替科室、院区、医保资格和预约可及性。',transport:'枢纽数量不能代替真实通勤体验；班次、接驳和最后一公里需要按具体地址核对。',culture:'地标与知名度只是起点；能否经常参与，还取决于距离、开放和预约安排。',education:'高校与科研资源不代表中小学入学资格，也不直接代表个人录取或就业结果。',nature:'景区资源与家门口的活动空间是两回事；距离、坡度、天气与无障碍条件都影响体验。'}[state.facet]}</p></div></aside></div>${facetCompare()}${facetMatrix()}<p class="caption" style="margin:19px 3px">切面档案整理：2026 年 10 月 3 日；经济基准仍为 2024 年。未加入未经统一核验的医院数量、地铁里程、机构排名或最新开放信息。</p>`;};
document.addEventListener('click',e=>{const t=e.target.closest('[data-facet],[data-resource],[data-facet-cell]');if(!t)return;if(t.dataset.facet){if(!FACET_TYPES[t.dataset.facet])return;state.facet=t.dataset.facet;state.resource=0;render();}else if(t.dataset.resource!==undefined){const i=Number(t.dataset.resource),f=facetFor(selected());if(!Number.isInteger(i)||!f?.resources[i])return;state.resource=i;document.querySelectorAll('[data-resource]').forEach(n=>{n.classList.toggle('selected',Number(n.dataset.resource)===i);n.setAttribute('aria-pressed',Number(n.dataset.resource)===i);});$('#facet-resource').innerHTML=facetResource(f);}else{const [id,key]=t.dataset.facetCell.split(':');if(!CITIES.some(c=>c.id===id)||!FACET_TYPES[key])return;state.facet=key;state.resource=0;setCity(id);document.querySelector('.facet-top').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}});
if(state.view==='facets')render();
